                <div className="work-caption"><div className="tag">{item.tag || 'AI Ad'}</div><h4>{item.title || `Reel ${index + 1}`}</h4></div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="process" id="process">
        <div className="wrap section" style={{ paddingBottom: 56 }}>
          <div>
            <div className="kicker on-dark">How We Work</div>
            <h2 className="section-title display">Our Proven Process.</h2>
          </div>
        </div>
        <div className="process-row">
          <div className="process-step"><div className="pnum display">01</div><h4>Discovery</h4><p>Product, audience and current ad performance.</p></div>
          <div className="process-step"><div className="pnum display">02</div><h4>Concept</h4><p>2–3 creative directions, storyboarded first.</p></div>
          <div className="process-step"><div className="pnum display">03</div><h4>Production</h4><p>AI-generated visuals, built fast, refined on feedback.</p></div>
          <div className="process-step"><div className="pnum display">04</div><h4>Launch</h4><p>Delivered ad-ready, with variants for testing.</p></div>
        </div>
        <div className="stats-row">
          <div className="stat"><div className="num display">250+</div><div className="label">Ads Produced</div></div>
          <div className="stat"><div className="num display">30+</div><div className="label">Brands Served</div></div>
          <div className="stat"><div className="num display">3x</div><div className="label">Faster Turnaround</div></div>
          <div className="stat"><div className="num display">98%</div><div className="label">Client Satisfaction</div></div>
        </div>
      </section>

      <section className="section pricing" id="pricing">
        <div className="wrap">
          <div style={{ marginBottom: 52 }}>
            <div className="kicker on-dark">Pricing</div>
            <h2 className="section-title display">{blocks.pricingTitle || 'Flexible Plans For Every Brand.'}</h2>
          </div>
          <div className="price-grid">
            {pricingPlans.map((plan, index) => (
              <div className={`price-card ${plan.popular ? 'popular' : ''}`} key={index}>
                {plan.popular && <div className="badge">Most Popular</div>}
                <div className="price-plan">{plan.name}</div>
                <div className="price-amount display">{plan.price}<span>/mo</span></div>
                <div className="price-list">
                  {(plan.features || []).map((feature) => <div key={feature}>✓ {feature}</div>)}
                </div>
                <a
                  href="#contact"
                  className="price-btn"
                  onClick={(e) => {
                    e.preventDefault();
                    handleNavigate('mailto:hello@motionfranzy.com?subject=' + encodeURIComponent(plan.name + ' pricing inquiry'));
                  }}
                >
                  Choose Plan
                </a>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="contact" id="contact">
        <div className="wrap">
          <div className="contact-wrapper">
            <div className="contact-info">
              <h2 className="display">Let's Talk.</h2>

              <div className="info-block">
                <div className="info-label">Email</div>
                <div className="info-value">
                  <a href="mailto:hello@motionfranzy.com">hello@motionfranzy.com</a>
                </div>
              </div>

              <div className="info-block">
                <div className="info-label">Phone</div>
                <div className="info-value">
                  <a href="tel:+15551234567">+1 (555) 123-4567</a>
                </div>
              </div>

              <div className="info-block">
                <div className="info-label">Location</div>
                <div className="info-value">
                  San Francisco, CA<br/>USA
                </div>
              </div>

              <div className="info-block">
                <div className="info-label">Hours</div>
                <div className="info-value">
                  Monday – Friday: 9am – 6pm PT<br/>Saturday – Sunday: By appointment
                </div>
              </div>

              <div className="info-block">
                <div className="info-label">Follow Us</div>
                <div className="info-value" style={{ display: 'flex', gap: '16px' }}>
                  <a href={footer.socialLinks?.instagram || 'https://instagram.com'} target="_blank" rel="noreferrer" style={{ fontSize: '14px', fontWeight: 700 }}>Instagram →</a>
                  <a href={footer.socialLinks?.linkedin || 'https://linkedin.com'} target="_blank" rel="noreferrer" style={{ fontSize: '14px', fontWeight: 700 }}>LinkedIn →</a>
                </div>
              </div>
            </div>

            <div className="contact-form">
              <h3 style={{ fontSize: '18px', fontWeight: 700, marginBottom: '28px' }}>Send us a message</h3>
              <form onSubmit={handleContactSubmit}>
                <div className="form-group">
                  <label>Your Name</label>
                  <input
                    type="text"
                    value={contactForm.name}
                    onChange={(e) => setContactForm({ ...contactForm, name: e.target.value })}
                    placeholder="John Doe"
                  />
                </div>

                <div className="form-group">
                  <label>Email Address</label>
                  <input
                    type="email"
                    value={contactForm.email}
                    onChange={(e) => setContactForm({ ...contactForm, email: e.target.value })}
                    placeholder="you@company.com"
                  />
                </div>

                <div className="form-group">
                  <label>Message</label>
                  <textarea
                    value={contactForm.message}
                    onChange={(e) => setContactForm({ ...contactForm, message: e.target.value })}
                    placeholder="Tell us about your project..."
                  />
                </div>

                <button type="submit" className="form-submit">Send Message →</button>
                {formStatus && <div className={`form-status ${formStatus.includes('filled') || formStatus.includes('error') ? 'error' : 'success'}`}>{formStatus}</div>}
              </form>
            </div>
          </div>
        </div>
      </section>

      <footer>
        <div className="wrap">
          <div className="foot-top">
            <div className="brand">
              <svg className="brand-mark" viewBox="0 0 100 100"><rect width="100" height="100" rx="20" fill="var(--red)"/><path d="M22 62 L34 40 L44 58 L54 38" stroke="var(--yellow)" strokeWidth="7" strokeLinecap="round" strokeLinejoin="round" fill="none"/><path d="M58 66 Q62 40 78 24" stroke="#0A0A0A" strokeWidth="7" strokeLinecap="round" fill="none"/><circle cx="80" cy="20" r="3.4" fill="#0A0A0A"/></svg>
              <div className="brand-word">{settings.brand?.logoText || 'MOTION FRANZY'} <span>{settings.brand?.logoTag || '/ AI ADS'}</span></div>
            </div>
            <div className="foot-cols">
              <div className="foot-col"><h5>Studio</h5><a href="#services" onClick={(e) => { e.preventDefault(); handleNavigate('#services'); }}>Services</a><a href="#work" onClick={(e) => { e.preventDefault(); handleNavigate('#work'); }}>Work</a><a href="#process" onClick={(e) => { e.preventDefault(); handleNavigate('#process'); }}>Process</a><a href="#pricing" onClick={(e) => { e.preventDefault(); handleNavigate('#pricing'); }}>Pricing</a></div>
              <div className="foot-col"><h5>Contact</h5><a href={footer.socialLinks?.instagram || 'https://instagram.com'} target="_blank" rel="noreferrer" onClick={(e) => { if (!footer.socialLinks?.instagram || footer.socialLinks.instagram === '#') { e.preventDefault(); handleNavigate('https://instagram.com'); } }}>Instagram</a><a href={footer.socialLinks?.linkedin || 'https://linkedin.com'} target="_blank" rel="noreferrer" onClick={(e) => { if (!footer.socialLinks?.linkedin || footer.socialLinks.linkedin === '#') { e.preventDefault(); handleNavigate('https://linkedin.com'); } }}>LinkedIn</a><a href="mailto:hello@motionfranzy.com" onClick={(e) => { e.preventDefault(); handleNavigate('mailto:hello@motionfranzy.com'); }}>Email</a></div>
            </div>
          </div>
          <div className="foot-bottom">
            <div>{footer.footerText || '© 2026 Motion Franzy. All rights reserved.'}</div>
            <div>{footer.description || 'AI ads and creative systems built for modern brands.'}</div>
          </div>
        </div>
      </footer>
    </>
  );
}

export default PricingPage;
